import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# Kernel source for per-element multiplication by a scalar.
multiply_scalar_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void multiply_scalar_kernel(const float* a, const float* s_val, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] * s_val;
    }
}

torch::Tensor multiply_scalar_cuda(torch::Tensor a, float s) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    multiply_scalar_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), &s, out.data_ptr<float>(), size);

    return out;
}
"""

multiply_scalar_cpp_source = (
    "torch::Tensor multiply_scalar_cuda(torch::Tensor a, float s);"
)

# Compile the inline CUDA code for element-wise multiplication by scalar.
mul_func = load_inline(
    name="multiply_scalar",
    cpp_sources=multiply_scalar_cpp_source,
    cuda_sources=multiply_scalar_kernel_source,
    functions=["multiply_scalar_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.multiply_scalar = mul_func

    def forward(self, A: torch.Tensor, s: float) -> torch.Tensor:
        return self.multiply_scalar.multiply_scalar_cuda(A, s)
